 "content": "def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    line_color = next((color for color, _ in counts.most_common() if color != background), background)

    # Long, dense rows and columns are the lattice rails.
    rows = [r for r, row in enumerate(grid)
            if sum(v != background for v in row) > w // 2]
    cols = [c for c in range(w)
            if sum(grid[r][c] != background for r in range(h)) > h // 2]

    result = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            color = corners[0]
            if color != background and color != line_color and all(v == color for v in corners):
                out_row.append(color)
            else:
                out_row.append(background)
        result.append(out_row)

    # Remove empty border cells, retaining any blank cells within the pattern.
    while result and all(v == background for v in result[0]):
        result.pop(0)
    while result and all(v == background for v in result[-1]):
        result.pop()
    while result and result[0] and all(row[0] == background for row in result):
        for row in result:
            row.pop(0)
    while result and result[0] and all(row[-1] == background for row in result):
        for row in result:
            row.pop()
    return result
